class CanonicalPolicy:
    def __init__(self, applicant, depth=4):
        self.prior = PRIORS[applicant - 1]
        self.depth = depth
        self.memo = {}

    def value(self, counts, belief, remaining=8):
        key = counts
        if key in self.memo:
            return self.memo[key][0]
        approve = float(belief @ EV)
        if remaining == 0 or sum(counts) >= self.depth:
            value = max(0.0, approve)
            action = "approve" if approve > 0.0 else "decline"
            self.memo[key] = (value, action, None)
            return value
        check_values = []
        for check_index, check in enumerate(CHECKS):
            likelihood = LIKELIHOOD[check]
            probabilities = likelihood.T @ belief
            continuation = 0.0
            for band in range(6):
                if probabilities[band] > 0.0:
                    child_counts = list(counts)
                    child_counts[check_index * 6 + band] += 1
                    child_belief = belief * likelihood[:, band]
                    child_belief /= child_belief.sum()
                    continuation += probabilities[band] * self.value(
                        tuple(child_counts), child_belief, remaining - 1
                    )
            check_values.append(continuation - 20.0)
        best_check_value = max(check_values)
        if approve >= 0.0 and approve >= best_check_value:
            value = approve
            action = "approve"
        elif best_check_value >= 0.0:
            value = best_check_value
            action = CHECKS[int(np.argmax(check_values))]
        else:
            value = 0.0
            action = "decline"
        self.memo[key] = (value, action, best_check_value)
        return value


